308	<script>
309	const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
310	let mode="released", busy=false;
311	const label={normal:"Ask normally",cut:"Cut the connection",agent:"Crash the agent"};
312	
313	$$("#toggle button").forEach(b=>b.onclick=()=>{ if(busy)return; mode=b.dataset.mode;
314	  $$("#toggle button").forEach(x=>{x.classList.toggle("sel",x===b);x.setAttribute("aria-checked",x===b)});
315	  $("#toggle").classList.toggle("fixed",mode==="fixed"); });
316	
317	function setRO(id,cls,val,sub){const el=$(id);el.className="ro "+cls;const v=el.querySelector(".val");v.textContent=val;v.classList.remove("flip");void v.offsetWidth;v.classList.add("flip");if(sub!==undefined)el.querySelector(".sub").textContent=sub;}
318	function step(s){const order=["calling","witness","reading","done"];const i=order.indexOf(s);$$("#steps .st").forEach((e,j)=>{e.className="st"+(j<i?" done":j===i?" act":"")});if(s==="done")$$("#steps .st").forEach(e=>e.className="st done");}
319	function annun(state,why){const a=$("#annun");a.className="annun"+(state==="on"?" on":state==="agree"?" agree":"");$("#lamp").textContent=state==="agree"?"AGREE":"DISAGREE";$("#why").textContent=why;}
320	function bot(html,crash){const m=$("#botMsg");m.className="bubble bot"+(crash?" crash":"");m.innerHTML=html;m.style.animation="none";void m.offsetWidth;m.style.animation="";}
321	const wire=$("#wire");
322	
323	$$(".go").forEach(b=>b.onclick=()=>run(b.dataset.break,b));
324	
325	async function run(brk,btn){
326	  if(busy)return; busy=true; $("#msg").textContent="";
327	  $$(".go").forEach(x=>x.disabled=true); btn.classList.add("running");
328	  setRO("#roReal","wait","…","Asking Claude through neatlogs' model key");
329	  setRO("#roRec","wait","…","Waiting for neatlogs");
330	  annun("off","Watching the wire…"); step("calling");
331	  $("#recList").innerHTML='<div class="note">Waiting for the run…</div>'; $("#recLink").textContent="";
332	  bot('<span class="typing"><span></span><span></span><span></span></span>');
333	  wire.className="wire on";
334	  try{
335	    const r=await fetch("/api/run",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({break:brk,mode})});
336	    const j=await r.json(); if(!r.ok) throw new Error(j.error||"Try again in a moment.");
337	    let job, shownResult=false;
338	    for(let i=0;i<70;i++){
339	      await new Promise(z=>setTimeout(z,1500));
340	      job=await (await fetch("/api/job/"+j.id)).json();
341	      if(job.stage==="failed") throw new Error(job.error||"The run failed.");
342	      if(job.result && !shownResult){ shownResult=true; showResult(brk,job.result); step("reading"); setRO("#roRec","wait","…","neatlogs is storing the record"); }
343	      if(job.stage==="done"){ showRecord(job.record, job.result); break; }
344	    }
345	    if(!job || job.stage!=="done") throw new Error("neatlogs is slow to store the record right now.");
346	  }catch(e){ $("#msg").textContent=e.message; wire.className="wire"; setRO("#roReal","idle","—","Waiting for your click"); setRO("#roRec","idle","—","Read back from neatlogs"); annun("off","The light turns on when the record says the opposite of what really happened."); step(""); bot("Pick a button below to send it."); }
347	  finally{ busy=false; $$(".go").forEach(x=>{x.disabled=false;x.classList.remove("running")}); refreshStats(); }
348	}
349	
350	function showResult(brk,res){
351	  step("witness");
352	  const crashed=res.really==="crashed";
353	  if(brk==="cut"){ wire.className="wire cut"; } else if(brk==="agent"){ wire.className="wire cut"; } else { wire.className="wire"; }
354	  if(crashed){
355	    bot(brk==="cut"?"⚠️ The reply stopped halfway: the connection was cut. I couldn't finish.":"⚠️ My agent run failed: the AI server refused the request.",true);
356	    setRO("#roReal","bad","CRASHED",(brk==="cut"?"Connection cut mid-reply":"Agent run failed")+" · app saw "+res.app);
357	  } else {
358	    bot(String(res.app||"Your refund lookup is ready.").replace(/[<>&#*]/g,"").trim());
359	    setRO("#roReal","ok","OK","The bot answered normally");
360	  }
361	  const d=res.disagreements||[];
362	  if(d.length){ annun("on","Witness: neatlogs' "+(d[0].field==="run_status"?"agent workflow":"AI step")+" says "+nice(d[0].record)+", but the run really "+(crashed?"crashed":"failed")+"."); }
363	  else { annun("agree",crashed?"The record says the run failed. It matches what really happened.":"Nothing broke, and the record says so."); }
364	}
365	function nice(s){return s==="OK"||s==="SUCCESS"?"SUCCESS":s}
366	
367	function showRecord(rec,res){
368	  step("done");
369	  const crashed=res.really==="crashed";
370	  if(!rec){ setRO("#roRec","idle","?","neatlogs had not stored it yet"); return; }
371	  const steps=rec.steps||[];
372	  const main=steps.find(s=>s.name==="Agent workflow"&&s.status==="ERROR")||steps.find(s=>s.name==="Agent workflow")||steps.find(s=>(s.type||"").toLowerCase()==="llm"||/claude|haiku|response/i.test(s.name||""))||steps[0];
373	  const st=main?main.status:rec.status;
374	  const lie=crashed && st!=="ERROR";
375	  setRO("#roRec",lie?"bad":(crashed?"ok":"ok"),st||"?",(main?main.name+" · ":"")+"trace "+(rec.trace_id||"").slice(0,8));
376	  $("#recList").innerHTML="";
377	  steps.forEach((s,i)=>{const row=document.createElement("div");row.className="rec"+(s.name==="TRACE DISAGREE"?" disagree":"");row.style.animationDelay=(i*90)+"ms";
378	    row.innerHTML='<span>'+(s.name==="TRACE DISAGREE"?"🔴 ":"")+(s.name||"step").replace(/[<>&]/g,"")+'</span><span class="chip '+(s.name==="TRACE DISAGREE"?"ERROR":(s.status||"UNSET"))+'">'+(s.name==="TRACE DISAGREE"?"WITNESS":(s.status||"UNSET"))+'</span>';
379	    $("#recList").appendChild(row);});
380	  $("#recLink").innerHTML='Trace <code>'+rec.trace_id+'</code> in the Trueup neatlogs project (neatlogs login to the project needed to open it).';
381	}
382	
383	async function refreshStats(){
384	  try{const s=await (await fetch("/api/stats")).json(); $("#today").textContent=s.today+" / "+s.cap;
385	    const t=s.totals||{}; const cell=(m,b)=>t[m+":"+b]||{runs:0,lit:0};
386	    const rows=[["cut","Cut the connection"],["agent","Crash the agent"],["normal","Ask normally"]];
387	    $("#tally").innerHTML=rows.map(([b,n])=>{const r=cell("released",b),f=cell("fixed",b);
388	      return '<div class="proof"><div class="label">'+n+'</div><div style="display:flex;gap:18px;flex-wrap:wrap"><div><div class="big" style="font-size:2rem"><span class="'+(r.lit?'r':'')+'">'+r.lit+'</span><span style="color:var(--dim);font-size:1.2rem"> / '+r.runs+'</span></div><p>light on · as released</p></div><div><div class="big" style="font-size:2rem;color:var(--green)">'+f.lit+'<span style="color:var(--dim);font-size:1.2rem"> / '+f.runs+'</span></div><p>light on · with fixes</p></div></div></div>'}).join("");
389	  }catch(e){}
390	}
391	refreshStats(); setInterval(refreshStats,15000);
392	
393	$("#copy").onclick=()=>{navigator.clipboard&&navigator.clipboard.writeText("import trueup.witness\ntrueup.witness.watch()");$("#copy").textContent="Copied";setTimeout(()=>$("#copy").textContent="Copy",1500)};
394	
395	const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("in");if(e.target.querySelector("#c1"))count();io.unobserve(e.target)}}),{threshold:.15});
396	$$(".reveal").forEach(e=>io.observe(e));
397	let counted=false;function count(){if(counted)return;counted=true;const a=$("#c1"),b=$("#c2");const t0=performance.now();
398	  (function f(t){const p=Math.min(1,(t-t0)/1400),e=1-Math.pow(1-p,3);a.textContent=(6.2*e).toFixed(1);b.textContent=(11.1*e).toFixed(1);if(p<1)requestAnimationFrame(f)})(t0);}
399	</script>
